('be5fd7d9-4902-597d-b5dc-710f353ae559', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Belgefîlma "Nanook of the North" piştî Şerê Cîhanê yê Duyem hate kişandin.', 'Rast', 'Şaş', '-', '-', 'B', 'Ew di sala 1922''yan de derket û wek yek ji belgefîlmên dirêj ên pêşîn tê hesibandin.', 'Ew di sala 1922''yan de derket û wek yek ji belgefîlmên dirêj ên pêşîn tê hesibandin.', '1922''de gösterime girdi ve uzun metrajlı ilk belgesellerden biri sayılır.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('8aaf4398-232e-5e73-85b2-e85308f6ca85', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di sînemaya klasîk de ji bo tevgereke xwezayî di çirkeyekê de 24 wêne tên nîşandan.', 'Rast', 'Şaş', '-', '-', 'A', 'Ev hejmar bi ketina deng re bû pîvana standard; berê ew ji 16 heta 20 diguherî.', 'Ev hejmar bi ketina deng re bû pîvana standard; berê ew ji 16 heta 20 diguherî.', 'Bu sayı, sesin filme girmesiyle standart ölçü oldu; öncesinde 16 ile 20 arasında değişiyordu.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('b2e3b7ef-76ca-574b-9bee-229308bb75d2', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ousmane Sembène, ku wek bavê sînemaya Afrîkayê tê hesibandin, ji kîjan welatî ye?', 'Misir', 'Senegal', 'Nîjerya', 'Afrîkaya Başûr', 'B', 'Ew berê romannivîs bû; berê xwe da sînemayê da ku gel bêyî xwendinê jî çîrokên wî bibihîze.', 'Ew berê romannivîs bû; berê xwe da sînemayê da ku gel bêyî xwendinê jî çîrokên wî bibihîze.', 'Önce romancıydı; halk okuma bilmeden de öykülerini duysun diye sinemaya yöneldi.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('d886b816-cbef-51e6-ad0c-79a40ac5b542', (select id from categories where slug = 'cihan'), 'ku-kmr', '"Don Kîşot" wek yekem romana nûjen a wêjeya Ewropayê tê hesibandin.', 'Rast', 'Şaş', '-', '-', 'A', 'Cervantes ew di destpêka sedsala 17em de nivîsî; şêwaza wî ya henekî bû mînak ji bo romanên paşerojê.', 'Cervantes ew di destpêka sedsala 17em de nivîsî; şêwaza wî ya henekî bû mînak ji bo romanên paşerojê.', 'Cervantes eseri 17. yüzyılın başında yazdı; alaycı üslubu sonraki romanlara örnek oldu.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('e0f2d66f-6d4b-5bd1-9e8f-0e4758fdc94c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kovara fransî di salên 1950î de nêrîna "derhêner nivîskarê fîlmî ye" belav kir?', 'Sight and Sound', 'Positif', 'Cahiers du cinéma', 'Variety', 'C', 'Rexnegirên ciwan ên li dora kovarê pêşniyar kirin ku heta di nav rêsayên stûdyoyê de jî mora şexsî ya derhênerekî tê xwendin; paşê wan bi xwe fîlm kişandin. Positif kovareke fransî ya reqîb e, Sight and Sound îngilîzî ye, Variety jî weşana sektorî ya amerîkî ye.', 'Rexnegirên ciwan ên li dora kovarê pêşniyar kirin ku heta di nav rêsayên stûdyoyê de jî mora şexsî ya derhênerekî tê xwendin; paşê wan bi xwe fîlm kişandin. Positif kovareke fransî ya reqîb e, Sight and Sound îngilîzî ye, Variety jî weşana sektorî ya amerîkî ye.', 'Dergi çevresindeki genç eleştirmenler, stüdyo düzeni içinde bile bir yönetmenin kişisel damgasının okunabileceğini savundu; sonra kendileri film çekti. Positif rakip Fransız dergisi, Sight and Sound İngiliz, Variety ise Amerikan sektör yayınıdır.', 4, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=812f622118f6e513', 'approved', 'Kurmancî', 2, now()),
('8c930d3c-7b2f-5527-b1db-65fd74060e7c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Xelatên Oscarê cara yekem di kîjan salê de hatin pêşkêşkirin?', '1919', '1939', '1949', '1929', 'D', 'Merasima yekem a Xelatên Akademiyê (Oscar) di 16''ê gulana 1929''an de li Hollywoodê hate lidarxistin. Ji wê demê vir ve Oscar her sal tê dayîn û bûye xelata herî bi prestîj a pîşesaziya fîlmê.', 'Merasima yekem a Xelatên Akademiyê (Oscar) di 16''ê gulana 1929''an de li Hollywoodê hate lidarxistin. Ji wê demê vir ve Oscar her sal tê dayîn û bûye xelata herî bi prestîj a pîşesaziya fîlmê.', 'Akademi Ödülleri''nin (Oscar) ilk töreni 16 Mayıs 1929''da Hollywood''da yapıldı. O zamandan beri Oscar her yıl verilir ve film endüstrisinin en prestijli ödülü hâline geldi.', 3, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
('c4db8369-94ba-500a-a652-ddd44ad668c0', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan festîvala fîlman a herî kevn a cîhanê ye?', 'Festîvala Cannesê', 'Festîvala Berlînê', 'Festîvala Venedîkê', 'Festîvala Lokarnoyê', 'C', 'Festîvala Venedîkê di sala 1932''an de hate damezrandin û wek festîvala fîlman a herî kevn a cîhanê tê zanîn. Cannes di sala 1946''an, Berlîn jî di sala 1951''ê de dest pê kirin.', 'Festîvala Venedîkê di sala 1932''an de hate damezrandin û wek festîvala fîlman a herî kevn a cîhanê tê zanîn. Cannes di sala 1946''an, Berlîn jî di sala 1951''ê de dest pê kirin.', 'Venedik Film Festivali 1932''de kuruldu ve dünyanın en eski film festivali olarak kabul edilir. Cannes 1946''da, Berlin ise 1951''de başladı.', 4, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
