('af127357-98e4-5a24-b744-26bf16dbe9d2', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Paytextê Brezîlyayê kîjan bajar e?', 'Rio de Janeiro', 'Sao Paulo', 'Brasilia', 'Salvador', 'C', 'Brasilia paytextê Brezîlyayê ye. Rio de Janeiro, Sao Paulo û Salvador bajarên mezin in lê ne paytext in.', 'Brasilia paytextê Brezîlyayê ye. Rio de Janeiro, Sao Paulo û Salvador bajarên mezin in lê ne paytext in.', 'Brasilia, Brezilya''nın başkentidir. Rio de Janeiro, Sao Paulo ve Salvador büyük şehirlerdir ancak başkent değildirler.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Brasília', NULL, 'https://en.wikipedia.org/wiki/Brasília', 'approved', 'Kurmancî', 1, now()),
('1259a721-ad64-5c9e-a092-d2dd9915be39', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Paytextê Îtalyayê kîjan bajar e?', 'Mîlano', 'Napolî', 'Roma', 'Tûrîn', 'C', 'Roma paytextê Îtalyayê ye. Mîlano, Napolî û Tûrîn bajarên mezin in lê ne paytext in.', 'Roma paytextê Îtalyayê ye. Mîlano, Napolî û Tûrîn bajarên mezin in lê ne paytext in.', 'Roma, İtalya''nın başkentidir. Milano, Napoli ve Torino büyük şehirlerdir ancak başkent değildirler.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Rome', NULL, 'https://en.wikipedia.org/wiki/Rome', 'approved', 'Kurmancî', 1, now()),
