('f5d30954-04c4-5a27-baa0-eabb534fcb37', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan amûr bi piranî di muzîka elektronîk de tê bikaranîn?', 'Sentezîzer', 'Sentor', 'Tembûr', 'Bilûr', 'A', 'Sentezîzer amûreke elektronîk e û di muzîka elektronîk de tê bikaranîn. Tembûr û bilûr amûrên akustîk in.', 'Sentezîzer amûreke elektronîk e û di muzîka elektronîk de tê bikaranîn. Tembûr û bilûr amûrên akustîk in.', 'Sentezleyici elektronik bir çalgıdır ve elektronik müzikte kullanılır. Tembur ve kaval akustik çalgılardır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Synthesizer', NULL, 'https://en.wikipedia.org/wiki/Synthesizer', 'approved', 'Kurmancî', 1, now()),
('f596c0be-670e-5411-970f-f5bc6d09bf73', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan amûr bi piranî di orkestraya klasîk de tê bikaranîn?', 'Keman', 'Tembûr', 'Bilûr', 'Def', 'A', 'Keman di orkestraya klasîk de amûreke sereke ye. Tembûr û def di muzîka gelêrî de ne.', 'Keman di orkestraya klasîk de amûreke sereke ye. Tembûr û def di muzîka gelêrî de ne.', 'Keman, klasik orkestrada ana çalgılardan biridir. Tembur ve def halk müziğinde kullanılır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Violin', NULL, 'https://en.wikipedia.org/wiki/Violin', 'approved', 'Kurmancî', 1, now()),
('b36f4203-716a-56fc-947a-5b8b18a3a112', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di muzîkê de têgeha ku dûrahiya du dengan diyar dike çi ye?', 'Pîvan', 'Tempo', 'Deng', 'Navber', 'D', 'Navber di muzîkê de dûrahiya di navbera du dengan de ye. Pîvan rêjeya demê, tempo leza muzîkê û deng jî xwezaya dengan e.', 'Navber di muzîkê de dûrahiya di navbera du dengan de ye. Pîvan rêjeya demê, tempo leza muzîkê û deng jî xwezaya dengan e.', 'Aralık müzikte iki ses arasındaki mesafedir. Ölçü zaman oranı, tempo müziğin hızı ve ses de seslerin doğasıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Interval_(music)', NULL, 'https://en.wikipedia.org/wiki/Interval_(music)', 'approved', 'Kurmancî', 1, now()),
('21404450-40b2-5898-a1fe-430242846bda', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di muzîkê de, kîjan têgîn ji bo nîşankirina leza muzîkê tê bikaranîn?', 'Rîtm', 'Aheng', 'Tempo', 'Melodî', 'C', 'Tempo di muzîkê de ji bo nîşankirina leza muzîkê tê bikaranîn. Rîtm rêjdana dengan e, aheng hevahengiya dengan e û melodî jî rêzika dengan e.', 'Tempo di muzîkê de ji bo nîşankirina leza muzîkê tê bikaranîn. Rîtm rêjdana dengan e, aheng hevahengiya dengan e û melodî jî rêzika dengan e.', 'Tempo, müzikte müziğin hızını belirtmek için kullanılır. Ritim seslerin düzenli akışıdır, armoni seslerin uyumudur ve melodi ise seslerin dizilişidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Tempo', NULL, 'https://en.wikipedia.org/wiki/Tempo', 'approved', 'Kurmancî', 1, now()),
('f7f2eaca-afe6-5ef3-9b91-39e694176dd1', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di muzîkê de, kîjan têgîn ji bo nîşankirina rêjdana dengan tê bikaranîn?', 'Tempo', 'Aheng', 'Melodî', 'Rîtm', 'D', 'Rîtm di muzîkê de ji bo nîşankirina rêjdana dengan tê bikaranîn. Tempo leza muzîkê ye, aheng hevahengiya dengan e û melodî jî rêzika dengan e.', 'Rîtm di muzîkê de ji bo nîşankirina rêjdana dengan tê bikaranîn. Tempo leza muzîkê ye, aheng hevahengiya dengan e û melodî jî rêzika dengan e.', 'Ritim, müzikte seslerin düzenli akışını belirtmek için kullanılır. Tempo müziğin hızıdır, armoni seslerin uyumudur ve melodi ise seslerin dizilişidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Rhythm', NULL, 'https://en.wikipedia.org/wiki/Rhythm', 'approved', 'Kurmancî', 1, now()),
('070e2d7e-2080-5878-943f-9712a845b163', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di muzîkê de, kîjan têgîn ji bo nîşankirina rêzika dengan tê bikaranîn?', 'Aheng', 'Rîtm', 'Melodî', 'Tempo', 'C', 'Melodî di muzîkê de ji bo nîşankirina rêzika dengan tê bikaranîn. Aheng hevahengiya dengan e, rîtm rêjdana demê ye û tempo jî leza muzîkê ye.', 'Melodî di muzîkê de ji bo nîşankirina rêzika dengan tê bikaranîn. Aheng hevahengiya dengan e, rîtm rêjdana demê ye û tempo jî leza muzîkê ye.', 'Melodi, müzikte seslerin dizilişini belirtmek için kullanılır. Armoni seslerin uyumudur, ritim zamansal akıştır ve tempo ise müziğin hızıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Melody', NULL, 'https://en.wikipedia.org/wiki/Melody', 'approved', 'Kurmancî', 1, now()),
('fbe447be-7c1f-5c57-b353-86711f80465a', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Wolfgang Amadeus Mozart di kîjan welatî de ji dayik bûye?', 'Almanya', 'Awistirya', 'Fransa', 'Îtalya', 'B', 'Mozart di sala 1756an de li bajarê Salzburgê, ku wê demê beşek ji Împaratoriya Romayê ya Pîroz bû û niha li Awistiryayê ye, ji dayik bûye.', 'Mozart di sala 1756an de li bajarê Salzburgê, ku wê demê beşek ji Împaratoriya Romayê ya Pîroz bû û niha li Awistiryayê ye, ji dayik bûye.', 'Mozart, 1756 yılında o dönem Kutsal Roma İmparatorluğu''nun bir parçası olan ve günümüzde Avusturya''da bulunan Salzburg şehrinde doğmuştur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Wolfgang_Amadeus_Mozart', NULL, 'https://en.wikipedia.org/wiki/Wolfgang_Amadeus_Mozart', 'approved', 'Kurmancî', 1, now()),
('a430b535-e2f4-584d-be7e-a2b737c1c53a', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Wolfgang Amadeus Mozart di kîjan salê de wefat kiriye?', '1809', '1756', '1827', '1791', 'D', 'Mozart di 5ê kanûna pêşîn a sala 1791ê de li Viyanayê wefat kiriye, di 35 saliya xwe de.', 'Mozart di 5ê kanûna pêşîn a sala 1791ê de li Viyanayê wefat kiriye, di 35 saliya xwe de.', 'Mozart, 5 Aralık 1791''de Viyana''da 35 yaşında vefat etmiştir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Wolfgang_Amadeus_Mozart', NULL, 'https://en.wikipedia.org/wiki/Wolfgang_Amadeus_Mozart', 'approved', 'Kurmancî', 1, now()),
