('7f56cb2f-d82a-5e78-99e6-9cb8d589e791', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ludwig van Beethoven di kîjan welatî de wefat kiriye?', 'Almanya', 'Awistirya', 'Fransa', 'Îtalya', 'B', 'Beethoven di 26ê adara sala 1827ê de li Viyanayê, Awistiryayê wefat kiriye.', 'Beethoven di 26ê adara sala 1827ê de li Viyanayê, Awistiryayê wefat kiriye.', 'Beethoven, 26 Mart 1827''de Avusturya''nın Viyana şehrinde vefat etmiştir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Ludwig_van_Beethoven', NULL, 'https://en.wikipedia.org/wiki/Ludwig_van_Beethoven', 'approved', 'Kurmancî', 1, now()),
('516508ba-c32a-5f7f-9a24-aa8d88c289b9', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan bestekarê klasîk bi navê "Bavê Senfoniyê" tê naskirin?', 'Joseph Haydn', 'Wolfgang Amadeus Mozart', 'Ludwig van Beethoven', 'Franz Schubert', 'A', 'Joseph Haydn ji ber hejmara zêde ya senfoniyên ku nivîsîne û bandora xwe ya li ser vê formê wekî "Bavê Senfoniyê" tê naskirin.', 'Joseph Haydn ji ber hejmara zêde ya senfoniyên ku nivîsîne û bandora xwe ya li ser vê formê wekî "Bavê Senfoniyê" tê naskirin.', 'Joseph Haydn, yazdığı çok sayıda senfoni ve bu form üzerindeki etkisi nedeniyle "Senfoninin Babası" olarak bilinir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Joseph_Haydn', NULL, 'https://en.wikipedia.org/wiki/Joseph_Haydn', 'approved', 'Kurmancî', 1, now()),
('acda6796-a0f7-5b50-bb9f-c97a1f67646e', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Joseph Haydn di kîjan salê de wefat kiriye?', '1791', '1809', '1827', '1756', 'B', 'Haydn di 31ê gulana sala 1809an de li Viyanayê wefat kiriye.', 'Haydn di 31ê gulana sala 1809an de li Viyanayê wefat kiriye.', 'Haydn, 31 Mayıs 1809''da Viyana''da vefat etmiştir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Joseph_Haydn', NULL, 'https://en.wikipedia.org/wiki/Joseph_Haydn', 'approved', 'Kurmancî', 1, now()),
