-- 2026-09-30: «Cîhan» kategorisi (166 soru) + Paradigma'ya 40 bilim sorusu (canlı sunucu).
--
-- NİÇİN: uygulamaya yeni `Cîhan` (Türkçe «Dünya») kategorisi geldi: Kürtlerle
-- doğrudan bağı olmayan nötr genel bilgi (dünya sineması, dünya coğrafyası,
-- tarih ve genel kültür; ürünün ~%30'u). Hızlı düello ve oda kurma konu
-- listesi sunucudaki `categories` tablosundan (is_active) geldiği için
-- kategori orada yoksa düello/odada görünmez. Ayrıca Paradigma
-- («Bilim ve Düşünce») 40 yeni kaynaklı soru aldı (bilim_0001…bilim_0040);
-- sunucuda Paradigma soruları çoğunlukla onaydan çıkarılmıştı
-- (2026-09-30_contested_questions_unapprove.sql).
--
-- KAÇ SORU: Cîhan 166; Paradigma'ya 40 (yeni, `bilim_` kimlikli).
--
-- SEÇİM KURALLARI (tool/sync_categories_to_server.py; seçim ve satır biçimi
-- tool/sync_sinema_to_server.py ile ortak, uygulamanın
-- QuestionContentPolicy.isPlayable kuralının Python karşılığı):
--   - question_bank_assets.dart bankaları; retired_question_ids.dart
--     emeklileri ve gizli kategoriler hariç;
--   - reviewStatus yok ya da approved; çoktan seçmelide tam 4 şık.
-- ATLANANLAR (sunucu şemasına sığmayan ya da görselsiz anlamını yitiren):
--   - (atlanan yok: seçim kümesindeki tüm sorular şemaya sığdı)
--
-- BİÇİM: metinler yalnız Kurmancî (prompt/şıklar); explanation = Kurmancî
-- açıklama; explanation_ku/explanation_tr yerel alanlardan. Hepsi
-- is_approved = true, review_status = 'approved'. Sunucu kategorisi
-- `Cîhan` (slug `cihan`) yeni oluşturulur; `paradigma` zaten vardır.
--
-- TEKRAR ÇALIŞTIRILABİLİR: kategori `where not exists` ile, sorular sabit
-- uuid5 kimlikleriyle (uuid5(ad alanı, "zankurd-local:" + yerel id), ad alanı
-- sync_sinema_to_server.py ile aynı) ve `on conflict (id) do nothing` ile
-- eklenir; ikinci çalıştırma 0 satır ekler. Tek işlemdir; doğrulama bloğu
-- beklenenin altında kalırsa işlem geri alınır.
--
-- GERİ ALMA (yalnız bu göçün satırları):
--   delete from questions where id in (<bu dosyadaki id'ler>);
--   delete from categories where slug = 'cihan' and not exists
--     (select 1 from questions where category_id = categories.id);
--
-- Uygulama: supabase db query --linked -f supabase/2026-09-30_cihan_and_science.sql

begin;

select 'Cîhan', 'cihan', true
where not exists (select 1 from categories where slug = 'cihan');

-- Cîhan (166)
on conflict (id) do nothing;

-- Paradigma / Bilim ve Düşünce (40 yeni soru)
on conflict (id) do nothing;

-- Doğrulama: beklenenin altındaysa işlem geri alınır.
do $$
declare
  v_cihan integer;
  v_sci integer;
  v_active boolean;
begin
  select is_active into v_active from categories where slug = 'cihan';
  if v_active is distinct from true then
    raise exception 'Cihan: kategori yok ya da pasif';
  end if;

  select count(*) into v_cihan
  from questions
  where category_id = (select id from categories where slug = 'cihan')
    and is_approved = true;
  if v_cihan < 166 then
    raise exception 'Cihan: beklenen en az 166 onayli soru, bulunan %', v_cihan;
  end if;

  select count(*) into v_sci
  from questions
  where id in ('4a2c7355-832e-5805-b506-bbbb1bc9500e', 'b5a1b9df-82db-5e83-865a-2e0a916cc1a4', '3d8290c9-c0b4-5ad6-b865-fd7e6f406503', 'c2e2e546-69ed-5b17-92fa-2e7e46905d23', 'ef102015-eec4-5b43-9743-55fd7c731245', 'e7d783a9-0429-5549-ac42-fc16bde666ef', '78702160-9637-5f76-850b-720f522e603a', '53a80524-316b-59a8-b2ab-a6a48e50914b', '84e44f6c-f10e-5b08-b989-d2921602b43e', 'b9c16027-1942-5e3d-a253-3afb68d795b5', 'f58da2dc-1af8-5fae-b50a-42959d480f91', '23e3daa1-e3e3-56f8-a3ab-b841cb32153a', '7280a086-0368-53f6-b802-79751a82cd63', 'f1ba2fd5-2544-528d-a24a-f77c0b380c0a', 'a0f4f095-2ff3-5b49-80cf-dcb48ec8d1db', 'f7c8c9b5-8a51-5898-a383-95b5e895892c', '53522189-c818-5f47-9562-ef73bb2c6bd6', 'c6819365-6fdc-58d4-8128-a1f3168f9c8e', 'ebbd9fd3-79c4-5736-987c-bddf96bdd25b', 'e52ae71b-cd0d-5d2d-9b7d-59ca2ddc66a1', '2ae95a49-f4dd-5e81-a03e-5d8f1b3e3180', '77e0a1b6-4c4f-5429-9fa3-c89e27cf81f3', 'b912c244-4022-59d0-900d-16d4c346c1a1', '5fd63242-c0d2-583e-9fbf-a4b48dce9793', 'af74e5cf-95a7-536f-917a-1efd6387837b', '48b7d49a-364c-5734-923a-ff054e406d54', 'd77718c8-e421-53e3-a16c-0179722f484e', 'c72adbfe-b686-5127-b698-f1c4b75091fb', 'd9794318-89ad-5e47-a752-94ce68e405d8', 'd475db53-8a48-5db3-8538-959b81f6e614', '5c8f1a58-c935-5c52-841e-5879e976bd2c', '1c1ba12a-a0a8-5d09-9a8f-dbef748ec4ca', 'bbf82056-333d-5242-b35f-a3be45512a96', '87fbc201-bc30-5da8-a149-55333e18b8c9', 'bd4c4cfa-9cbc-54c6-b5ea-ba3fa75ed267', 'aef19552-103a-5772-950f-74b351adf1e4', '7159567c-1b58-54cc-9c8c-54acf26bb2e5', '25e4d1a8-50d2-584d-9a3f-1ea1a2ecbe42', '90ac7e83-dd13-5ee1-a13c-c047ae0a6cbf', '3cb1959f-6e00-50b5-a375-ca1070b46b78')
    and category_id = (select id from categories where slug = 'paradigma')
    and is_approved = true;
  if v_sci <> 40 then
    raise exception 'Bilim: beklenen 40 onayli Paradigma sorusu, bulunan %', v_sci;
  end if;
end
$$;

commit;
